var g=UnityEditor.Selection.activeGameObject;return new{selected=g?g.name:null,objects=g?g.GetComponentsInChildren<MeshRenderer>(true).Take(6).Select(r=>new{name=r.name,size=r.bounds.size.ToString(),materials=r.sharedMaterials.Where(m=>m).Select(m=>new{name=m.name,shader=m.shader.name,scale=m.HasProperty("_BaseMap")?m.GetTextureScale("_BaseMap").ToString():null,offset=m.HasProperty("_BaseMap")?m.GetTextureOffset("_BaseMap").ToString():null}).ToArray(),uv=r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh?r.GetComponent<MeshFilter>().sharedMesh.uv.Take(8).Select(v=>v.ToString()).ToArray():null}).ToArray():null};
